#version 330
#extension GL_ARB_separate_shader_objects : require

uniform sampler2D InSampler;
uniform sampler2D InDepthSampler;

layout(std140) uniform SamplerInfo {
    vec2 OutSize;
    vec2 InSize;
    vec2 InDepthSize;
};

layout(std140) uniform OutlineConfig {
    vec4 LineColor;
    float Threshold;
};

layout(location = 0) in vec2 texCoord;
layout(location = 0) out vec4 fragColor;

float depthAt(vec2 offset) {
    return texture(InDepthSampler, texCoord + offset / InDepthSize).r;
}

void main() {
    vec3 color = texture(InSampler, texCoord).rgb;
    // Reversed depth: 1 is near, 0 is the far plane (and the sky).
    float d = depthAt(vec2(0.0));
    float jump = max(max(abs(depthAt(vec2(1.0, 0.0)) - d), abs(depthAt(vec2(-1.0, 0.0)) - d)),
                     max(abs(depthAt(vec2(0.0, 1.0)) - d), abs(depthAt(vec2(0.0, -1.0)) - d)));
    // Depth is roughly proportional to 1 / distance, so a relative jump finds edges at any distance.
    float edge = step(Threshold, jump / max(d, 1e-5));
    fragColor = vec4(mix(color, LineColor.rgb, edge * LineColor.a), 1.0);
}
